  "claims": [
    {
      "text": "Yes—as a matter of Manual practice, if costs have been awarded against you, you are sent a copy of the bill of costs and allowed 21 days to comment as part of the taxation process.",
      "quotes": [
        {
          "ref": "TMM/Part55/4#1",
          "quote": "A copy of the bill of costs is sent to the party against whom costs have been awarded and 21 days allowed for their comments."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "That opportunity to comment on the bill is distinct from the statutory requirement to give each party a reasonable opportunity to be heard before costs are awarded.",
      "quotes": [
        {
          "ref": "TMM/Part55/4#1",
          "quote": "A copy of the bill of costs is sent to the party against whom costs have been awarded and 21 days allowed for their comments."
        },
        {
          "ref": "TMR1995/r21.12(3)",
          "quote": "(3) Before awarding costs in respect of the proceedings, the Registrar must give each party to the proceedings a reasonable opportunity to be heard in relation to the award of costs."
        }
      ],
      "authority": "both"
    },
    {
      "text": "Under regulation 21.13, costs must be taxed, allowed and certified by an employee appointed by the Registrar.",
      "quotes": [
        {
          "ref": "TMR1995/r21.13",
          "quote": "(2) The costs must be taxed, allowed and certified by an employee appointed by the Registrar."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "If the amount is challenged, the Manual says the Registrar may review the taxation taking account of the parties’ submissions; the Regulations confer a power to review, rather than requiring a review.",
      "quotes": [
        {
          "ref": "TMM/Part55/4#1",
          "quote": "If the amount of costs is challenged, the Registrar may review the taxation of costs taking into account any submissions from the parties (subreg 21.13(4))."
        },
        {
          "ref": "TMR1995/r21.13",
          "quote": "(3) The Registrar may review the taxation of costs by the employee."
        }
      ],
      "authority": "both"
    }
  ],
  "declined": false,
  "concepts_used": [
    "GC-0046"
  ]
}
